      beijing = 4011,
      dialog = 3,
      mask = "memory",
      music = "19_Daily02",
      renwu = "npc",
      sentence = "It was all because the red carpet host we had booked suddenly couldn't make it, and so me with my journalist experience had to step in at the last minute.",
