    [12] = {
      beijing = 4011,
      dialog = 3,
      mask = "memory",
      music = "19_Daily02",
      renwu = "npc",
      sentence = "But because of nerves, I babbled on too much a few times, and I even made some puns. That same night, videos and parody memes about me started spreading like wildfire.",
